// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    receive() external payable {}
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount < type(uint256).max / 2);
        vm.deal(address(c), amount);
        uint256 balBefore = address(this).balance;
        uint256 cBefore = address(c).balance;
        c.withdrawAll();
        assertTrue(address(this).balance - balBefore == cBefore && address(c).balance == 0);
    }
}
